local Logs=HolyStorm:RegisterRequiredModule("Logs");HolyStorm:ApplyModuleMetadata(Logs,{displayName="Logs",internalName="logs",version=addonVersion,category="required",description="Technical log table and export",permissions={"logs-view"},dependencies={"core","ui"},enabledByDefault=true})
local function json(v)if v==nil then return"null"elseif type(v)=="boolean"or type(v)=="number"then return tostring(v)elseif type(v)=="string"then return'"'..v:gsub('\\','\\\\'):gsub('"','\\"'):gsub('\n','\\n')..'"'elseif type(v)=="table"then local array=true;local count=0;for k in pairs(v)do count=count+1;if type(k)~="number"then array=false end end;local out={};if array then for i=1,count do out[#out+1]=json(v[i])end;return"["..table.concat(out,",").."]"end;for k,x in pairs(v)do out[#out+1]=json(tostring(k))..":"..json(x)end;table.sort(out);return"{"..table.concat(out,",").."}"end;return"null"end
function Logs:GetFiltered()local out={};local q=string.lower(self.search or"");for _,e in ipairs(HolyStorm.Logger:GetHistory())do if(not self.level or e.level==self.level)and(q==""or string.lower((e.source or"").." "..(e.category or"").." "..(e.message or"")):find(q,1,true))then out[#out+1]=e end end;return out end
function Logs:Export(format,all)local entries=all and HolyStorm.Logger:GetHistory()or self:GetFiltered();if format=="json"then return json(entries)end;local lines={};if format=="csv"then lines[1]='timestamp,level,module,category,message';for _,e in ipairs(entries)do local function q(v)return'"'..tostring(v or""):gsub('"','""')..'"'end;lines[#lines+1]=table.concat({q(e.timestamp),q(e.level),q(e.source),q(e.category),q(e.message)},",")end else for _,e in ipairs(entries)do lines[#lines+1]=string.format("%s [%s] [%s/%s] %s",date("%Y-%m-%d %H:%M:%S",e.timestamp),e.level,e.source,e.category,e.message)end end;return table.concat(lines,"\n")end
function Logs:SetPaused(value)self.paused=value==true;if not self.paused then self:Render()end end;function Logs:SetAutoScroll(value)self.autoScroll=value==true end;function Logs:SetLevel(level)self.level=level;self:Render()end;function Logs:Refresh()self:Render()end
