function Logs:Render()if not self.page:IsShown()or self.paused then return end;local lines={"TIME      | LEVEL | MODULE       | CATEGORY     | MESSAGE"};for _,e in ipairs(self:GetFiltered())do lines[#lines+1]=string.format("%s | %-5s | %-12s | %-12s | %s",date("%H:%M:%S",e.timestamp),e.level,e.source,e.category,e.message)end;self.text:SetText(table.concat(lines,"\n"));self.content:SetHeight(math.max(self.scroll:GetHeight(),self.text:GetStringHeight()+12));if self.autoScroll then self.scroll:SetVerticalScroll(math.max(0,self.content:GetHeight()-self.scroll:GetHeight()))end end
function Logs:OnInitialize()local UI=HolyStorm:GetModule("UI",true);local p=CreateFrame("Frame",nil,UI.content);local search=CreateFrame("EditBox",nil,p,"SearchBoxTemplate");search:SetSize(240,24);search:SetPoint("TOPLEFT",18,-18);search:SetScript("OnTextChanged",function(x)Logs.search=x:GetText();Logs:Render()end);local clear=CreateFrame("Button",nil,p,"UIPanelButtonTemplate");clear:SetSize(80,24);clear:SetPoint("LEFT",search,"RIGHT",8,0);clear:SetText(CLEAR);clear:SetScript("OnClick",function()if HolyStorm.Permissions:Has("logs-clear")then HolyStorm.Logger:Clear()end end);local scroll=CreateFrame("ScrollFrame",nil,p,"UIPanelScrollFrameTemplate");scroll:SetPoint("TOPLEFT",18,-54);scroll:SetPoint("BOTTOMRIGHT",-28,18);local content=CreateFrame("Frame",nil,scroll);content:SetSize(1,1);scroll:SetScrollChild(content);local text=content:CreateFontString(nil,"OVERLAY","GameFontHighlightSmall");text:SetPoint("TOPLEFT",4,-4);text:SetJustifyH("LEFT");self.page,self.scroll,self.content,self.text,self.autoScroll=p,scroll,content,text,true;scroll:SetScript("OnSizeChanged",function(x)content:SetWidth(x:GetWidth());Logs:Render()end);HolyStorm.UI:RegisterPage("logs",p,"Holy Storm — Logs",function()Logs:Render()end,{"HS_LOG_ADDED","HS_LOG_CLEARED"});HolyStorm.UI:AddNavigation("logs",12,"Interface\\Icons\\INV_Misc_Note_01","Logs","Technical logs",function()HolyStorm.UI:ShowPage("logs")end)end
